import math, heapq
# graph adjacency in (y,x), no diagonal when orthogonal bridge exists
def make_graph(ci):
 pts=set(zip(*np.where(sl==ci))); adj={p:set() for p in pts}
 for y,x0 in pts:
  for dy in (-1,0,1):
   for dx in (-1,0,1):
    if dy==dx==0:continue
    q=(y+dy,x0+dx)
    if q in pts and not(dy and dx and ((y+dy,x0) in pts or (y,x0+dx) in pts)):
     adj[(y,x0)].add(q)
 return pts,adj

def dijkstra(adj,s):
 dist={s:0.}; prev={}
 pq=[(0.,s)]
 while pq:
  d,u=heapq.heappop(pq)
  if d!=dist[u]:continue
  for v in adj[u]:
   w=math.sqrt(2) if v[0]!=u[0] and v[1]!=u[1] else 1.
   nd=d+w
   if nd<dist.get(v,1e30):dist[v]=nd;prev[v]=u;heapq.heappush(pq,(nd,v))
 return dist,prev

def getpath(prev,s,t):
 p=[t]
 while p[-1]!=s:p.append(prev[p[-1]])
 return p[::-1]

def minpair(T, paths):
 if not T:return []
 cache={}
 def rec(mask):
  if not mask:return (0.,[])
  if mask in cache:return cache[mask]
  i=(mask&-mask).bit_length()-1; rest=mask^(1<<i); best=(1e30,None)
  for j in range(i+1,len(T)):
   if rest>>j&1:
    new=rest^(1<<j); d=paths[(i,j)][0]+rec(new)[0]
    if d<best[0]:best=(d,[(i,j)]+rec(new)[1])
  cache[mask]=best;return best
 return rec((1<<len(T))-1)[1]

def chinese_postman(ci,sxy,txy):
 pts,adj=make_graph(ci)
 s=(sxy[1],sxy[0]);t=(txy[1],txy[0]); assert s in pts and t in pts
 odd=[p for p in pts if len(adj[p])%2]
 T=list(set(odd)^set([s,t]))
 dprev={}; pairinfo={}
 for i,a in enumerate(T):
  dist,prev=dijkstra(adj,a);dprev[a]=prev
  for j in range(i+1,len(T)):
   b=T[j]; pairinfo[(i,j)]=(dist[b],getpath(prev,a,b))
 pairs=minpair(T,pairinfo)
 edges=[]; neigh={p:[] for p in pts}; eid=0
 for a in pts:
  for b in adj[a]:
   if a<b:
    edges.append((a,b));neigh[a].append((eid,b));neigh[b].append((eid,a));eid+=1
 dup=[]
 for i,j in pairs:
  pp=pairinfo[(i,j)][1];dup+=list(zip(pp[:-1],pp[1:]))
 for a,b in dup:
  edges.append((a,b));neigh[a].append((eid,b));neigh[b].append((eid,a));eid+=1
 used=set();stack=[s];trail=[]
 while stack:
  u=stack[-1]
  while neigh[u] and neigh[u][-1][0] in used:neigh[u].pop()
  if not neigh[u]:trail.append(stack.pop())
  else:
   e,v=neigh[u].pop()
   if e in used:continue
   used.add(e);stack.append(v)
 route=trail[::-1]
 assert route[0]==s and route[-1]==t and len(used)==len(edges),(ci,route[0],route[-1],s,t,len(used),len(edges))
 return np.array([[p[1],p[0]] for p in route],float),len(dup),len(odd),len(route)

def rdp(points,eps):
 if len(points)<=2:return points
 a,b=points[0],points[-1]; d=b-a; den=np.linalg.norm(d)
 if den==0:dist=np.linalg.norm(points[1:-1]-a,axis=1)
 else:dist=np.abs(d[0]*(a[1]-points[1:-1,1])- (a[0]-points[1:-1,0])*d[1])/den
 if not len(dist) or dist.max()<=eps:return np.array([a,b])
 k=int(np.argmax(dist))+1
 l=rdp(points[:k+1],eps);r=rdp(points[k:],eps)
 return np.vstack((l[:-1],r))

